6	namespace CcDirector.Core.Tests.Browsers;
7	
8	/// <summary>
9	/// Tests for the per-repository "Open in Browser" default in <see cref="BrowserDefaultStore"/>.
10	/// The contract (devthrottle #1112): a repository can remember its own browser+profile keyed by
11	/// repository path, stored separately from the global <c>browser.default</c>, and
12	/// <see cref="BrowserDefaultStore.Resolve"/> picks in order repository default -> global default ->
13	/// null (caller uses the OS default). All methods share an isolated CC_DIRECTOR_ROOT set in the
14	/// constructor; the CcStorageRoot collection serializes the root-mutating tests so they never race.
15	///
16	/// These tests deliberately never touch <see cref="BrowserDefaultStore.ResolveBrowser"/> or the
17	/// real browser detector, so they are deterministic on any machine regardless of what is installed:
18	/// the stored exe paths are arbitrary strings and we only assert on the persisted
19	/// <see cref="BrowserDefault"/> values.
20	/// </summary>
21	[Collection("CcStorageRoot")] // serializes all classes that mutate the process-wide CC_DIRECTOR_ROOT
22	public sealed class RepoBrowserDefaultStoreTests : IDisposable
23	{
24	    // Arbitrary, non-existent exe/profile pairs. They are never resolved to an installed browser,
25	    // so the values only need to be distinct strings for the assertions to be meaningful.
26	    private const string GlobalExe = @"C:\Programs\GlobalBrowser\global.exe";
27	    private const string GlobalProfile = "Global Profile";
28	    private const string RepoExe = @"C:\Programs\RepoBrowser\repo.exe";
29	    private const string RepoProfile = "Repo Profile";
30	
31	    private const string RepoPath = @"D:\ReposFred\some-work-repo";
32	
33	    private readonly string _root;
34	    private readonly string? _prevRoot;
35	
36	    public RepoBrowserDefaultStoreTests()
37	    {
38	        _prevRoot = Environment.GetEnvironmentVariable("CC_DIRECTOR_ROOT");
39	        _root = Path.Combine(Path.GetTempPath(), "ccd-repobrowser-test-" + Guid.NewGuid().ToString("N"));
40	        Environment.SetEnvironmentVariable("CC_DIRECTOR_ROOT", _root);
41	    }
42	
43	    public void Dispose()
44	    {
45	        Environment.SetEnvironmentVariable("CC_DIRECTOR_ROOT", _prevRoot);
46	        try { if (Directory.Exists(_root)) Directory.Delete(_root, recursive: true); } catch { /* best effort */ }
47	    }
48	
49	    private static void SeedConfig(string json)
50	    {
51	        var path = CcStorage.ConfigJson();
52	        var dir = Path.GetDirectoryName(path);
53	        Assert.NotNull(dir);
54	        Directory.CreateDirectory(dir);
55	        File.WriteAllText(path, json);
56	    }
57	
58	    // -- Resolve order: repository default -> global default -> null (Definition of done #7) --
59	
60	    [Fact]
61	    public void Resolve_RepoDefaultPresent_ReturnsRepoDefaultNotGlobal()
62	    {
63	        BrowserDefaultStore.Save(new BrowserDefault(GlobalExe, GlobalProfile));
64	        BrowserDefaultStore.SaveForRepo(RepoPath, new BrowserDefault(RepoExe, RepoProfile));
65	
66	        var resolved = BrowserDefaultStore.Resolve(RepoPath);
67	
68	        Assert.NotNull(resolved);
69	        Assert.Equal(RepoExe, resolved!.ExePath);
70	        Assert.Equal(RepoProfile, resolved.ProfileFolder);
71	    }
72	
73	    [Fact]
74	    public void Resolve_NoRepoDefaultButGlobalPresent_ReturnsGlobalDefault()
75	    {
76	        BrowserDefaultStore.Save(new BrowserDefault(GlobalExe, GlobalProfile));
77	
78	        var resolved = BrowserDefaultStore.Resolve(RepoPath);
79	
80	        Assert.NotNull(resolved);
81	        Assert.Equal(GlobalExe, resolved!.ExePath);
82	        Assert.Equal(GlobalProfile, resolved.ProfileFolder);
83	    }
