85	    [Fact]
86	    public void Resolve_NeitherRepoNorGlobalPresent_ReturnsNull()
87	    {
88	        // Nothing saved: the caller would fall through to the OS default browser.
89	        var resolved = BrowserDefaultStore.Resolve(RepoPath);
90	
91	        Assert.Null(resolved);
92	    }
