using System.Text.Json;
using CcDirector.Core.Browsers;
using CcDirector.Core.Storage;
using Xunit;

namespace CcDirector.Core.Tests.Browsers;

/// <summary>
/// Tests for the per-repository "Open in Browser" default in <see cref="BrowserDefaultStore"/>.
/// The contract (devthrottle #1112): a repository can remember its own browser+profile keyed by
/// repository path, stored separately from the global <c>browser.default</c>, and
/// <see cref="BrowserDefaultStore.Resolve"/> picks in order repository default -> global default ->
/// null (caller uses the OS default). All methods share an isolated CC_DIRECTOR_ROOT set in the
/// constructor; the CcStorageRoot collection serializes the root-mutating tests so they never race.
///
/// These tests deliberately never touch <see cref="BrowserDefaultStore.ResolveBrowser"/> or the
/// real browser detector, so they are deterministic on any machine regardless of what is installed:
/// the stored exe paths are arbitrary strings and we only assert on the persisted
/// <see cref="BrowserDefault"/> values.
/// </summary>
[Collection("CcStorageRoot")] // serializes all classes that mutate the process-wide CC_DIRECTOR_ROOT
public sealed class RepoBrowserDefaultStoreTests : IDisposable
{
    // Arbitrary, non-existent exe/profile pairs. They are never resolved to an installed browser,
    // so the values only need to be distinct strings for the assertions to be meaningful.
    private const string GlobalExe = @"C:\Programs\GlobalBrowser\global.exe";
    private const string GlobalProfile = "Global Profile";
    private const string RepoExe = @"C:\Programs\RepoBrowser\repo.exe";
    private const string RepoProfile = "Repo Profile";

    private const string RepoPath = @"D:\ReposFred\some-work-repo";

    private readonly string _root;
    private readonly string? _prevRoot;

    public RepoBrowserDefaultStoreTests()
    {
        _prevRoot = Environment.GetEnvironmentVariable("CC_DIRECTOR_ROOT");
        _root = Path.Combine(Path.GetTempPath(), "ccd-repobrowser-test-" + Guid.NewGuid().ToString("N"));
        Environment.SetEnvironmentVariable("CC_DIRECTOR_ROOT", _root);
    }

    public void Dispose()
    {
        Environment.SetEnvironmentVariable("CC_DIRECTOR_ROOT", _prevRoot);
        try { if (Directory.Exists(_root)) Directory.Delete(_root, recursive: true); } catch { /* best effort */ }
    }

    private static void SeedConfig(string json)
    {
        var path = CcStorage.ConfigJson();
        var dir = Path.GetDirectoryName(path);
        Assert.NotNull(dir);
        Directory.CreateDirectory(dir);
        File.WriteAllText(path, json);
    }

    // -- Resolve order: repository default -> global default -> null (Definition of done #7) --

    [Fact]
    public void Resolve_RepoDefaultPresent_ReturnsRepoDefaultNotGlobal()
    {
        BrowserDefaultStore.Save(new BrowserDefault(GlobalExe, GlobalProfile));
        BrowserDefaultStore.SaveForRepo(RepoPath, new BrowserDefault(RepoExe, RepoProfile));

        var resolved = BrowserDefaultStore.Resolve(RepoPath);

        Assert.NotNull(resolved);
        Assert.Equal(RepoExe, resolved!.ExePath);
        Assert.Equal(RepoProfile, resolved.ProfileFolder);
    }

    [Fact]
    public void Resolve_NoRepoDefaultButGlobalPresent_ReturnsGlobalDefault()
    {
        BrowserDefaultStore.Save(new BrowserDefault(GlobalExe, GlobalProfile));

        var resolved = BrowserDefaultStore.Resolve(RepoPath);

        Assert.NotNull(resolved);
        Assert.Equal(GlobalExe, resolved!.ExePath);
        Assert.Equal(GlobalProfile, resolved.ProfileFolder);
    }

    [Fact]
    public void Resolve_NeitherRepoNorGlobalPresent_ReturnsNull()
    {
        // Nothing saved: the caller would fall through to the OS default browser.
        var resolved = BrowserDefaultStore.Resolve(RepoPath);

        Assert.Null(resolved);
    }

    [Fact]
    public void Resolve_NullRepoPath_ReturnsGlobalDefault()
    {
        // A session with no repository resolves straight to the global default.
        BrowserDefaultStore.Save(new BrowserDefault(GlobalExe, GlobalProfile));

        var resolved = BrowserDefaultStore.Resolve(null);

        Assert.NotNull(resolved);
        Assert.Equal(GlobalExe, resolved!.ExePath);
        Assert.Equal(GlobalProfile, resolved.ProfileFolder);
    }

    // -- Durability and isolation (Definition of done #1) --

    [Fact]
    public void SaveForRepo_RoundTripsThroughDisk()
    {
        BrowserDefaultStore.SaveForRepo(RepoPath, new BrowserDefault(RepoExe, RepoProfile));

        // Re-read straight from config.json (the store reads fresh each call, no in-memory cache),
        // so this asserts the persisted value, i.e. it would survive an app restart.
        var loaded = BrowserDefaultStore.LoadForRepo(RepoPath);

        Assert.NotNull(loaded);
        Assert.Equal(RepoExe, loaded!.ExePath);
        Assert.Equal(RepoProfile, loaded.ProfileFolder);
    }

    [Fact]
    public void SaveForRepo_DoesNotDisturbGlobalDefault()
    {
        BrowserDefaultStore.Save(new BrowserDefault(GlobalExe, GlobalProfile));

        BrowserDefaultStore.SaveForRepo(RepoPath, new BrowserDefault(RepoExe, RepoProfile));

        // The global default must survive the repository write untouched.
        var global = BrowserDefaultStore.Load();
        Assert.NotNull(global);
        Assert.Equal(GlobalExe, global!.ExePath);
        Assert.Equal(GlobalProfile, global.ProfileFolder);
    }

    [Fact]
    public void SaveForRepo_PreservesUnrelatedConfigKeys()
    {
        SeedConfig("""{ "default_session_mode": "Studio", "brain_model": "claude-opus-4-8" }""");

        BrowserDefaultStore.SaveForRepo(RepoPath, new BrowserDefault(RepoExe, RepoProfile));

        var json = File.ReadAllText(CcStorage.ConfigJson());
        using var doc = JsonDocument.Parse(json);
        Assert.Equal("Studio", doc.RootElement.GetProperty("default_session_mode").GetString());
        Assert.Equal("claude-opus-4-8", doc.RootElement.GetProperty("brain_model").GetString());
        // And the repository default landed under browser.repoDefaults, not browser.default.
        var browser = doc.RootElement.GetProperty("browser");
        Assert.True(browser.TryGetProperty("repoDefaults", out _));
        Assert.False(browser.TryGetProperty("default", out _));
    }

    [Fact]
    public void SaveForRepo_TwoRepos_KeepIndependentDefaults()
    {
        const string otherRepo = @"D:\ReposFred\other-repo";
        const string otherExe = @"C:\Programs\OtherBrowser\other.exe";
        const string otherProfile = "Other Profile";

        BrowserDefaultStore.SaveForRepo(RepoPath, new BrowserDefault(RepoExe, RepoProfile));
        BrowserDefaultStore.SaveForRepo(otherRepo, new BrowserDefault(otherExe, otherProfile));

        var first = BrowserDefaultStore.LoadForRepo(RepoPath);
        var second = BrowserDefaultStore.LoadForRepo(otherRepo);

        Assert.NotNull(first);
        Assert.Equal(RepoExe, first!.ExePath);
        Assert.NotNull(second);
        Assert.Equal(otherExe, second!.ExePath);
    }

    // -- Path-key normalization: the same repository maps to the same entry regardless of --
    // -- trailing slash, forward vs back slash, or letter case (Definition of done #1/#7).   --

    [Theory]
    [InlineData(@"D:\ReposFred\some-work-repo\")]        // trailing separator
    [InlineData(@"D:/ReposFred/some-work-repo")]         // forward slashes
    [InlineData(@"D:\reposfred\SOME-WORK-REPO")]         // different letter case
    [InlineData(@"d:/ReposFred/some-work-repo/")]        // all three at once
    public void LoadForRepo_PathVariantOfSameRepo_HitsSameEntry(string variant)
    {
        BrowserDefaultStore.SaveForRepo(RepoPath, new BrowserDefault(RepoExe, RepoProfile));

        var loaded = BrowserDefaultStore.LoadForRepo(variant);

        Assert.NotNull(loaded);
        Assert.Equal(RepoExe, loaded!.ExePath);
        Assert.Equal(RepoProfile, loaded.ProfileFolder);
    }

    [Theory]
    [InlineData(@"D:\ReposFred\some-work-repo\")]
    [InlineData(@"D:/ReposFred/some-work-repo")]
    [InlineData(@"D:\reposfred\SOME-WORK-REPO")]
    public void Resolve_PathVariantOfSameRepo_HitsSameRepoDefault(string variant)
    {
        // Global present too, to prove the variant still resolves to the REPO entry, not the global.
        BrowserDefaultStore.Save(new BrowserDefault(GlobalExe, GlobalProfile));
        BrowserDefaultStore.SaveForRepo(RepoPath, new BrowserDefault(RepoExe, RepoProfile));

        var resolved = BrowserDefaultStore.Resolve(variant);

        Assert.NotNull(resolved);
        Assert.Equal(RepoExe, resolved!.ExePath);
        Assert.Equal(RepoProfile, resolved.ProfileFolder);
    }

    [Fact]
    public void SaveForRepo_PathVariant_OverwritesSameEntryNotAddsSecond()
    {
        // Saving under a case/slash variant of an existing key updates the same entry.
        BrowserDefaultStore.SaveForRepo(RepoPath, new BrowserDefault(RepoExe, RepoProfile));
        BrowserDefaultStore.SaveForRepo(@"d:/reposfred/some-work-repo/", new BrowserDefault(GlobalExe, GlobalProfile));

        var loaded = BrowserDefaultStore.LoadForRepo(RepoPath);
        Assert.NotNull(loaded);
        Assert.Equal(GlobalExe, loaded!.ExePath);
        Assert.Equal(GlobalProfile, loaded.ProfileFolder);

        // Exactly one entry under browser.repoDefaults, confirming the variant did not add a peer.
        var json = File.ReadAllText(CcStorage.ConfigJson());
        using var doc = JsonDocument.Parse(json);
        var repoDefaults = doc.RootElement.GetProperty("browser").GetProperty("repoDefaults");
        var count = 0;
        foreach (var _ in repoDefaults.EnumerateObject()) count++;
        Assert.Equal(1, count);
    }
}
